-- Get IDs for the missing types
SET @nutritionist_id = (SELECT id FROM businessTypes WHERE name = 'Nutritionist' LIMIT 1);
SET @massage_id = (SELECT id FROM businessTypes WHERE name = 'Sport Massage Therapist' LIMIT 1);
SET @vacation_id = (SELECT id FROM businessTypes WHERE name = 'Sport Vacation Provider' LIMIT 1);
SET @psych_id = (SELECT id FROM businessTypes WHERE name = 'Sport Psychologist' LIMIT 1);

-- Carolina Holzmann - nutritionist
INSERT INTO businesses (name, slug, description, website, phone, city, country, region, hub, businessTypeId, sportCategoryId, isActive, isFeatured)
SELECT 'Carolina Holzmann', 'carolina-holzmann', 'Nutritionist and dietitian in Palma de Mallorca with over 30 years of experience, specializing in digestive, cardiovascular, and metabolic disorders.', 'https://carolinaholzmann.com/en/', '669 872 206', 'Palma de Mallorca', 'Spain', 'Mallorca', 'Palma', bt.id, sc.id, 1, 0
FROM businessTypes bt, sportCategories sc WHERE bt.name = 'Nutritionist' AND sc.slug = 'cycling' LIMIT 1;

-- Vida Sports Therapy
INSERT INTO businesses (name, slug, description, website, phone, city, country, region, hub, businessTypeId, sportCategoryId, isActive, isFeatured)
SELECT 'Vida Sports Therapy', 'vida-sports-therapy', 'Mobile sports massage therapy in Mallorca, specializing in treatments for cyclists, runners, and other sports enthusiasts.', 'https://vidasportstherapy.com/', '+34 711 028 371', 'Mallorca', 'Spain', 'Mallorca', 'Palma', bt.id, sc.id, 1, 0
FROM businessTypes bt, sportCategories sc WHERE bt.name = 'Sport Massage' AND sc.slug = 'cycling' LIMIT 1;

-- Mitoura Sports & Events
INSERT INTO businesses (name, slug, description, website, phone, city, country, region, hub, businessTypeId, sportCategoryId, isActive, isFeatured)
SELECT 'Mitoura Sports & Events', 'mitoura-sports-events', 'Travel agency specializing in creating tailor-made sports experiences in Mallorca and other Mediterranean destinations.', 'https://www.mitourasportsevents.com/en/', '+34 971 14 61 61', 'Mallorca', 'Spain', 'Mallorca', 'Palma', bt.id, sc.id, 1, 0
FROM businessTypes bt, sportCategories sc WHERE bt.name LIKE '%Vacation%' AND sc.slug = 'cycling' LIMIT 1;

-- Running Mallorca
INSERT INTO businesses (name, slug, description, website, phone, city, country, region, hub, businessTypeId, sportCategoryId, isActive, isFeatured)
SELECT 'Running Mallorca', 'running-mallorca', 'Running trips and training camps for passionate runners. Variety of terrains from scenic coastal paths to tough mountain trails.', 'https://runningmallorca.com/', '+34662639020', 'Alaró', 'Spain', 'Mallorca', 'Alaró', bt.id, sc.id, 1, 0
FROM businessTypes bt, sportCategories sc WHERE bt.name = 'Coach' AND sc.slug = 'trail-running' LIMIT 1;

-- ShiftGrit Psychology
INSERT INTO businesses (name, slug, description, website, phone, city, country, region, hub, businessTypeId, sportCategoryId, isActive, isFeatured)
SELECT 'ShiftGrit Psychology & Counselling', 'shiftgrit-psychology', 'Sports psychology services in Calgary, using an identity-level approach to help athletes overcome mental blocks and achieve peak performance.', 'https://shiftgrit.com/calgary/sports-psychology/', '+1 (587) 352-6463', 'Calgary', 'Canada', 'Alberta', 'Calgary', bt.id, sc.id, 1, 0
FROM businessTypes bt, sportCategories sc WHERE bt.name LIKE '%Psycholog%' AND sc.slug = 'running' LIMIT 1;

